def outer(api, log):
    size = 50

    def inner():
        page = 1
        out = []
        while True:
            r = api.get(page=page)
            out.extend(r["items"])
            if page >= r["total_pages"]:
                break
            page += 1
        return out

    log.info("size %d", size)
    return inner()

